contract InvMutTest {
    C c;
    uint constant THRESHOLD = 1000;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public payable {
        require(v < 2**128);
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool reverted;
        // this contract acts as the token: its fallback reverts transferFrom when v > THRESHOLD
        try c.transfer(from, address(this), tos, v) returns (bool ok) {
            reverted = false;
            assert(ok && v <= THRESHOLD);
        } catch {
            reverted = true;
            assert(v > THRESHOLD);
        }
        assert(reverted == (v > THRESHOLD));
    }
    fallback(bytes calldata data) external returns (bytes memory) {
        if (data.length >= 100) {
            uint v;
            assembly { v := calldataload(68) }
            if (v > THRESHOLD) revert();
        }
        return "";
    }
    receive() external payable {}
}

